/*
 * Combine all enrichment data into comprehensive contact record
 */

const originalEmail = $('📝 Input: Email Address').first().json.email;
const validationData = $('✅ Validate Email').first().json || {};
const profileData = $('👤 Get Profile from Email').first().json || {};
const mobileData = $('📱 Find Mobile Number').first().json || {};

return {
  contact: {
    email: originalEmail,
    email_verified: validationData.deliverable || false,
    email_score: validationData.score || 0,

    first_name: profileData.first_name || '',
    last_name: profileData.last_name || '',
    full_name: profileData.full_name || `${profileData.first_name || ''} ${profileData.last_name || ''}`.trim(),

    job_title: profileData.job_title || profileData.title || '',
    company: profileData.company || profileData.current_company || '',
    location: profileData.location || '',

    mobile_number: mobileData.mobile_number || mobileData.phone || '',
    mobile_verified: !!mobileData.mobile_number,

    linkedin_url: profileData.profile_url || profileData.linkedin_url || '',

    work_history: (profileData.work_history || profileData.positions || []).slice(0, 5),
    skills: (profileData.skills || []).slice(0, 10)
  },
  meta: {
    enriched_at: new Date().toISOString(),
    data_sources: ['email_validation', 'profile_lookup', 'mobile_finder'],
    credits_used: null,
    completeness: [
      profileData.full_name ? 'name' : null,
      profileData.job_title ? 'title' : null,
      profileData.company ? 'company' : null,
      mobileData.mobile_number ? 'mobile' : null,
      profileData.linkedin_url ? 'linkedin' : null
    ].filter(Boolean)
  }
};
